/**
 * Tesseract's glyphless font (`tessdata/pdf.ttf` of tesseract-ocr, Apache-2.0,
 * Copyright Google Inc.; licence text in ../vendor/tesseract/LICENSE-Apache-2.0.txt):
 * a 572-byte TrueType with two glyphs and no outlines. The OCR text layer draws every
 * character with its blank glyph, so the text is there for search and copy but has no
 * ink anywhere. SHA-256 checked by tests/engine/ocr-layer.test.ts.
 */
export const GLYPHLESS_TTF_SHA256 = 'c7845420925a23d88ed830a63957b8af85a66a8daf8d9fc90e843673b2ef1a59';

const B64 =
	'';

export function glyphlessTtf(): Uint8Array {
	const bin = atob(B64);
	const out = new Uint8Array(bin.length);
	for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
	return out;
}
